package iso.tool;
import java.nio.file.*; import java.util.*; import java.util.stream.Collectors;
public final class Main { public static void main(String[] a)throws Exception{if(a.length==0||"--gui".equalsIgnoreCase(a[0])){UnifiedGui.launch();return;}Path root=Paths.get(a[0]);Path out=Paths.get(a.length>1?a[1]:"iso-tool-output");Files.createDirectories(out.resolve("manifests"));DependencyDetector.write(out.resolve("manifests/dependencies.json"));List<Path>py=PythonParityScanner.scan(root);Files.write(out.resolve("manifests/python-modules.txt"),py.stream().map(Path::toString).sorted().collect(Collectors.toList()));System.out.println("ISO-Tool Java parity scan: "+py.size()+" Python modules");} }
